    "code": "import java.util.Scanner;\npublic class Solution {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (sc.hasNextInt()) {\n            int r = sc.nextInt();\n            int c = sc.nextInt();\n            int[][] a = new int[r][c];\n            for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) a[i][j] = sc.nextInt();\n            boolean found = false;\n            for (int i = 0; i < r; i++) {\n                int minCol = 0;\n                for (int j = 1; j < c; j++) {\n                    if (a[i][j] < a[i][minCol]) minCol = j;\n                }\n                boolean isSaddle = true;\n                for (int k = 0; k < r; k++) {\n                    if (a[k][minCol] > a[i][minCol]) isSaddle = false;\n                }\n                if (isSaddle) {\n                    System.out.println(a[i][minCol]);\n                    found = true;\n                    break;\n                }\n            }\n            if (!found) System.out.println(\"-1\");\n        }\n    }\n}",
