    "code": "#include <iostream>\n#include <vector>\n#include <deque>\nusing namespace std;\nint main() {\n    int n, k;\n    if (cin >> n >> k) {\n        vector<int> arr(n);\n        for (int i = 0; i < n; i++) cin >> arr[i];\n        deque<int> dq;\n        vector<int> res;\n        for (int i = 0; i < n; i++) {\n            if (!dq.empty() && dq.front() == i - k) dq.pop_front();\n            while (!dq.empty() && arr[dq.back()] <= arr[i]) dq.pop_back();\n            dq.push_back(i);\n            if (i >= k - 1) res.push_back(arr[dq.front()]);\n        }\n        for (size_t i = 0; i < res.size(); i++) cout << res[i] << (i == res.size() - 1 ? \"\" : \" \");\n        cout << \"\\n\";\n    }\n    return 0;\n}",
