    "code": "#include <iostream>\n#include <string>\n#include <stack>\n#include <cctype>\nusing namespace std;\nint prec(char c) {\n    if (c == '+' || c == '-') return 1;\n    if (c == '*' || c == '/') return 2;\n    if (c == '^') return 3;\n    return 0;\n}\nint main() {\n    string s;\n    if (cin >> s) {\n        stack<char> st;\n        string res = \"\";\n        for (char ch : s) {\n            if (isalnum(ch)) res += ch;\n            else if (ch == '(') st.push(ch);\n            else if (ch == ')') {\n                while (!st.empty() && st.top() != '(') { res += st.top(); st.pop(); }\n                if (!st.empty()) st.pop();\n            } else {\n                while (!st.empty() && prec(st.top()) >= prec(ch)) { res += st.top(); st.pop(); }\n                st.push(ch);\n            }\n        }\n        while (!st.empty()) { res += st.top(); st.pop(); }\n        cout << res << \"\\n\";\n    }\n    return 0;\n}",
