    "code": "import java.util.*;\npublic class Solution {\n    static void bt(int target, int start, int[] coins, List<Integer> path) {\n        if (target == 0) {\n            System.out.print(\"[\");\n            for (int i = 0; i < path.size(); i++) System.out.print(path.get(i) + (i == path.size() - 1 ? \"\" : \" \"));\n            System.out.print(\"] \");\n            return;\n        }\n        for (int i = start; i < coins.length; i++) {\n            if (coins[i] > target) break;\n            path.add(coins[i]);\n            bt(target - coins[i], i, coins, path);\n            path.remove(path.size() - 1);\n        }\n    }\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (sc.hasNextInt()) {\n            int n = sc.nextInt(), target = sc.nextInt();\n            int[] coins = new int[n];\n            for (int i = 0; i < n; i++) coins[i] = sc.nextInt();\n            Arrays.sort(coins);\n            bt(target, 0, coins, new ArrayList<>());\n            System.out.println();\n        }\n    }\n}",
